ALTER TABLE public.consultation_requests ADD COLUMN request_key uuid UNIQUE, ADD COLUMN notification_status text NOT NULL DEFAULT 'not_requested' CHECK (notification_status IN ('not_requested','pending','sending','sent','failed')), ADD COLUMN notification_provider_id text, ADD COLUMN notification_error_code text, ADD COLUMN notification_http_status integer, ADD COLUMN notification_attempted_at timestamptz;
ALTER TABLE public.patient_intake_submissions ADD COLUMN request_key uuid UNIQUE, ADD COLUMN notification_status text NOT NULL DEFAULT 'not_requested' CHECK (notification_status IN ('not_requested','pending','sending','sent','failed')), ADD COLUMN notification_provider_id text, ADD COLUMN notification_error_code text, ADD COLUMN notification_http_status integer, ADD COLUMN notification_attempted_at timestamptz;
ALTER TABLE public.dentist_referral_submissions ADD COLUMN request_key uuid UNIQUE, ADD COLUMN notification_status text NOT NULL DEFAULT 'not_requested' CHECK (notification_status IN ('not_requested','pending','sending','sent','failed')), ADD COLUMN notification_provider_id text, ADD COLUMN notification_error_code text, ADD COLUMN notification_http_status integer, ADD COLUMN notification_attempted_at timestamptz;
COMMENT ON COLUMN public.consultation_requests.notification_status IS 'sent means accepted by Resend, not confirmed inbox delivery; historical records are not_requested';
COMMENT ON COLUMN public.patient_intake_submissions.notification_status IS 'sent means accepted by Resend, not confirmed inbox delivery; historical records are not_requested';
COMMENT ON COLUMN public.dentist_referral_submissions.notification_status IS 'sent means accepted by Resend, not confirmed inbox delivery; historical records are not_requested';